import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Desktop","description":"","frontmatter":{},"headers":[],"relativePath":"self-hosted/desktop.md","filePath":"self-hosted/desktop.md","lastUpdated":1788855895000}'),r={name:"self-hosted/desktop.md"};function n(i,e,h,l,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h1><p>Memoh Desktop is the native client for Memoh Cloud or a self-hosted Memoh server. It packages the same Web UI into an Electron shell with native windows, tray, menus, and keyboard integration, and it can register the computer it runs on as a <strong>Computer</strong> that your bots can use.</p><p>Desktop does <strong>not</strong> run its own local server or database. You always connect it to a Memoh server: either <a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a> or your own <a href="/self-hosted/docker.html">Server Deploy</a>.</p><h2 id="when-to-use-desktop" tabindex="-1">When to use Desktop <a class="header-anchor" href="#when-to-use-desktop" aria-label="Permalink to &quot;When to use Desktop&quot;">​</a></h2><p>Choose Desktop when you want:</p><ul><li>a native app window and system tray instead of a browser tab</li><li>native menus and keyboard shortcuts for the daily Memoh workflow</li><li>to let server-side bots use this computer&#39;s files, shell, and browser without running a separate runtime process</li></ul><p>Use the Web UI directly if you only need occasional access from a browser.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Download the installer for your platform (macOS DMG, Windows NSIS, or Linux AppImage/deb/rpm) from the <a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">Memoh Desktop download page</a>.</li><li>Open Memoh.</li><li>On the connect screen, enter your server address (or pick Memoh Cloud).</li><li>Sign in with your Memoh account.</li></ol><h2 id="connecting-to-a-server" tabindex="-1">Connecting to a server <a class="header-anchor" href="#connecting-to-a-server" aria-label="Permalink to &quot;Connecting to a server&quot;">​</a></h2><p>On the connect screen, enter the server address and connect:</p><ul><li>A bare domain such as <code>memoh.example.com</code> is assumed to be <code>https://</code> (only localhost addresses default to <code>http://</code>).</li><li>The <code>/api</code> path suffix is appended automatically when missing, so entering just the domain is enough.</li><li>Desktop probes the server&#39;s <code>/ping</code> endpoint (5-second timeout) before proceeding, then takes you to sign-in.</li></ul><p>Switching to a different server clears the local sign-in state, so you will authenticate against the new server.</p><h2 id="sharing-this-computer-with-bots" tabindex="-1">Sharing this computer with bots <a class="header-anchor" href="#sharing-this-computer-with-bots" aria-label="Permalink to &quot;Sharing this computer with bots&quot;">​</a></h2><p>Desktop can register the machine it runs on as a <strong>Computer</strong> that server-side bots can work on, without running a separate runtime process. Enable <strong>This computer</strong>, give it a name, and Desktop keeps the connection alive in the background using the embedded Memoh runtime SDK. Credentials are stored with the OS secure storage.</p><p>See <a href="/guides/computers.html">Computers</a> for the permission model, per-bot setup, and what bots can do on a connected computer.</p><h2 id="what-desktop-manages" tabindex="-1">What Desktop manages <a class="header-anchor" href="#what-desktop-manages" aria-label="Permalink to &quot;What Desktop manages&quot;">​</a></h2><ul><li>the application window, tray icon, reopen and quit behavior</li><li>native menus wired to the same command registry as the Web UI</li><li>the connection to the selected server and its cached sign-in state</li><li>the optional Remote Runtime connection for <strong>This computer</strong></li></ul><p>Everything else (bots, sessions, memory, workspaces, channels) lives on the server you connected to. Workspace runtimes are configured server-side; see <a href="/self-hosted/workspace-backends.html">Workspace Backends</a>.</p>',19)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
